CREATE VIEW 'energy_usd_factor_asof' AS ( 
DECLARE OVERRIDABLE @asof := now()
                SELECT i.symbol, i.px_factor * coalesce(x.usd, 1.0) AS factor
                FROM energy_instruments i
                LEFT JOIN energy_fx_asof x ON x.symbol = i.fx_symbol
);

